const assignAsset = asyncHandler(async (req, res) => {
  const { userId } = req.body;

  const targetUser = await User.findById(userId);
  if (!targetUser) {
    throw ApiError.notFound("User not found");
  }

  if (!targetUser.isActive) {
    throw ApiError.badRequest("Cannot assign asset to an inactive user");
  }

  // Atomic conditional update ensuring only an AVAILABLE asset is assigned
  const asset = await Asset.findOneAndUpdate(
    { _id: req.params.id, status: "AVAILABLE" },
    { $set: { status: "ASSIGNED", assignedTo: targetUser._id } },
    { new: true }
  ).populate("assignedTo", "name email");

  if (!asset) {
    const exists = await Asset.findById(req.params.id);
    if (!exists) {
      throw ApiError.notFound("Asset not found");
    }
    throw ApiError.badRequest("Asset is not available");
  }

const VALID_TRANSITIONS = {
  OPEN: ["IN_PROGRESS"],
  IN_PROGRESS: ["RESOLVED"],
  RESOLVED: ["IN_PROGRESS", "CLOSED"],
  CLOSED: []
};

/**
 * Checks if status transition from -> to is valid per business rules
 * @param {string} from - Source status
 * @param {string} to - Target status
 * @returns {boolean}
 */
function canTransition(from, to) {
  if (!from || !to) return false;
  if (from === to) return false;
  const allowed = VALID_TRANSITIONS[from];
  if (!allowed) return false;
  return allowed.includes(to);
}

licenseSchema.virtual("status").get(function () {
  if (!this.expiryDate) return "ACTIVE";
  const today = startOfToday();
  const expiry = new Date(this.expiryDate);
  expiry.setHours(0, 0, 0, 0);

  if (expiry.getTime() < today.getTime()) {
    return "EXPIRED";
  }
  const thirtyDaysAhead = addDays(today, 30);
  if (expiry.getTime() <= thirtyDaysAhead.getTime()) {
    return "EXPIRING";
  }
  return "ACTIVE";
});
